import { type DocumentNode, print } from "graphql";
import { describe, expect, it } from "vitest";
// Every operation the web app sends, as generated by its GraphQL Codegen (committed in apps/web/gql).
import * as webDocuments from "../../web/gql/graphql";
import { setupTestApi } from "./helpers";

const { gql } = setupTestApi();

const operations = Object.entries(webDocuments)
  .filter(
    (entry): entry is [string, DocumentNode] =>
      entry[0].endsWith("Document") && (entry[1] as DocumentNode)?.kind === "Document",
  )
  .map(([name, doc]) => [name.replace(/Document$/, ""), print(doc)] as const);

describe("web app operations", () => {
  it("finds the generated documents", () => {
    expect(operations.length).toBeGreaterThan(10);
  });

  // Validation (schema + depth/alias/token/cost limits) happens before execution, so no data or
  // variables are needed: any rejection here would be a rejection in production.
  it.each(operations)("%s passes the API's validation and query limits", async (_name, query) => {
    const result = await gql(query);
    const rejected =
      result.errors?.filter((e) =>
        /limit|exceeded|Cannot query field|Unknown|is not defined/i.test(e.message),
      ) ?? [];
    expect(rejected).toEqual([]);
  });
});
